<?php require __DIR__.'/config/bootstrap.php';$st=db()->prepare("SELECT * FROM pages WHERE slug=? AND status='published'");$st->execute([$_GET['slug']??'']);$p=$st->fetch();if(!$p){http_response_code(404);exit('404');}$title=$p['seo_title']?:$p['title'];$description=$p['seo_description']?:excerpt($p['content']);require __DIR__.'/includes/header.php';?><article class="article"><h1><?=e($p['title'])?></h1><div class="article-content"><?=$p['content']?></div></article><?php require __DIR__.'/includes/footer.php';?>